package io.github.rebrowser.ui;

import static org.junit.Assert.*;
import io.github.rebrowser.R;
import io.github.rebrowser.browser.HistoryStore;
import io.github.rebrowser.browser.SearchEngines;
import io.github.rebrowser.settings.SettingsRepository;
import java.util.*;
import org.junit.Test;

/** Actual production projection/resolution/intent guard, synthetic history values only.
 * No Android View/IME/decode/native navigation or website qualification. */
public final class NewTabNativeModelTest {
    static SettingsRepository.Snapshot settings(SearchEngines.Provider p){return new SettingsRepository.Snapshot(4,p,false,false);}
    static HistoryStore.Entry entry(int n,String url,Long expiry){return new HistoryStore.Entry(String.format("hv_%032x",n),String.format("ws_%032x",1),String.format("tab_%032x",1),"来源","标题"+n,url,n,expiry,n);}
    static HistoryStore.Snapshot history(HistoryStore.Entry... entries){return new HistoryStore.Snapshot(0,false,Arrays.asList(entries));}
    @Test public void oneActualConfiguredEngineNotAnIndependentBingSelector(){for(SearchEngines.Provider p:SearchEngines.Provider.values()){NewTabView.Model m=NewTabView.Model.fromNative(settings(p),null,0);assertEquals(p,m.provider());assertTrue(m.photo());assertTrue(m.empty());assertTrue(m.sameSettings(settings(p)));}assertThrows(IllegalArgumentException.class,()->NewTabView.Model.fromNative(null,null,0));}
    @Test public void recentUsesLatestEightDistinctFullUrlsWithoutMutatingHistory(){List<HistoryStore.Entry> rows=new ArrayList<>();for(int n=1;n<=12;n++)rows.add(entry(n,"https://example.test/"+n,null));rows.add(entry(13,"https://example.test/12",null));HistoryStore.Snapshot h=new HistoryStore.Snapshot(1,false,rows);NewTabView.Model m=NewTabView.Model.fromNative(settings(SearchEngines.Provider.GOOGLE),h,20);assertEquals(8,m.shortcuts().size());assertEquals("标题13",m.shortcuts().get(0).title());assertEquals(13,h.entries().size());assertEquals("https://example.test/5",NewTabView.Model.resolveRecent(m.shortcuts().get(7),h,20).url());}
    @Test public void fullUrlNotHostIsDeduplicationKey(){HistoryStore.Snapshot h=history(entry(1,"https://example.test/a?q=1#one",null),entry(2,"https://example.test/a?q=1#two",null),entry(3,"https://example.test/a?q=2#two",null));assertEquals(3,NewTabView.Model.fromNative(settings(SearchEngines.Provider.BING),h,5).shortcuts().size());}
    @Test public void exactExpiryIsNotShown(){HistoryStore.Snapshot h=history(entry(1,"https://example.test/old",10L),entry(2,"https://example.test/live",11L));NewTabView.Model m=NewTabView.Model.fromNative(settings(SearchEngines.Provider.BING),h,10);assertEquals(1,m.shortcuts().size());assertEquals("标题2",m.shortcuts().get(0).title());}
    @Test public void maintainModeKeepsTimedRecentRowsWithoutRenewingThem(){HistoryStore.Entry e=entry(1,"https://example.test/",10L);HistoryStore.Snapshot h=new HistoryStore.Snapshot(0,true,Arrays.asList(e));assertEquals(1,NewTabView.Model.fromNative(settings(SearchEngines.Provider.BING),h,20).shortcuts().size());assertEquals(Long.valueOf(10),h.entries().get(0).expiresUtcMs());}
    @Test public void actualRecentOffSuppressesRows(){SettingsRepository.Snapshot off=settings(SearchEngines.Provider.BING).withNewTab(SettingsRepository.NewTabBackground.EXCLUSIVE,false);assertTrue(NewTabView.Model.fromNative(off,history(entry(1,"https://example.test/",null)),5).empty());}
    @Test public void missingOptionalHistoryDoesNotInventPromotionsOrFavorites(){NewTabView.Model m=NewTabView.Model.fromNative(settings(SearchEngines.Provider.BAIDU),null,10);assertTrue(m.empty());assertEquals(SearchEngines.Provider.BAIDU,m.provider());assertThrows(UnsupportedOperationException.class,()->m.shortcuts().add(new NewTabView.Shortcut(new Object(),"t","h")));}
    @Test public void clickRechecksDeletion(){HistoryStore.Entry e=entry(1,"https://example.test/",null);NewTabView.Shortcut s=NewTabView.Model.fromNative(settings(SearchEngines.Provider.BING),history(e),2).shortcuts().get(0);assertThrows(IllegalStateException.class,()->NewTabView.Model.resolveRecent(s,history(),2));}
    @Test public void clickRechecksExpiryNotCachedDisplayUrl(){HistoryStore.Entry e=entry(1,"https://example.test/",10L);NewTabView.Shortcut s=NewTabView.Model.fromNative(settings(SearchEngines.Provider.BING),history(e),2).shortcuts().get(0);assertThrows(IllegalStateException.class,()->NewTabView.Model.resolveRecent(s,history(e),10));assertEquals("https://example.test/",NewTabView.Model.resolveRecent(s,history(e),9).url());}
    @Test public void sameIdDifferentUrlCannotRetargetOldClick(){HistoryStore.Entry e=entry(1,"https://example.test/original",null);NewTabView.Shortcut s=NewTabView.Model.fromNative(settings(SearchEngines.Provider.BING),history(e),2).shortcuts().get(0);assertThrows(IllegalStateException.class,()->NewTabView.Model.resolveRecent(s,history(entry(1,"https://example.test/replaced",null)),2));}
    @Test public void genericShortcutOrFavoriteTokenIsNotNativeRecent(){NewTabView.Shortcut s=new NewTabView.Shortcut(new Object(),"t","example.test");assertThrows(IllegalArgumentException.class,()->NewTabView.Model.resolveRecent(s,history(entry(1,"https://example.test/",null)),2));}
    @Test public void unicodeHostAndSupplementaryBadgeAreNotSplitOrIdnRewritten(){HistoryStore.Entry e=entry(1,"https://例子.测试/",null);NewTabView.Shortcut s=NewTabView.Model.fromNative(settings(SearchEngines.Provider.BING),history(e),2).shortcuts().get(0);assertEquals("例子.测试",s.hostLabel());assertEquals("例",s.badge());assertEquals("https://例子.测试/",NewTabView.Model.resolveRecent(s,history(e),2).url());assertEquals("\ud801\udc00",new NewTabView.Shortcut(new Object(),"t","\ud801\udc28.example").badge());}
    @Test public void emptyTitleFallsBackToHostNotRemoteFavicon(){HistoryStore.Entry e=new HistoryStore.Entry(String.format("hv_%032x",1),String.format("ws_%032x",1),String.format("tab_%032x",1),"","","https://www.example.test/path",1,null,1);NewTabView.Shortcut s=NewTabView.Model.fromNative(settings(SearchEngines.Provider.BING),history(e),2).shortcuts().get(0);assertEquals("example.test",s.title());assertEquals("E",s.badge());}
    @Test public void titleChangesDoNotRetargetOriginalUrl(){HistoryStore.Snapshot h=history(entry(1,"https://example.test/",null));NewTabView.Shortcut s=NewTabView.Model.fromNative(settings(SearchEngines.Provider.BING),h,2).shortcuts().get(0);HistoryStore.Entry e=h.entries().get(0);assertEquals("https://example.test/",NewTabView.Model.resolveRecent(s,h.updateTitle(e.id(),e.url(),"新标题"),2).url());}
    @Test public void onlyRelevantNewTabPreferencesInvalidateDisplayedSettings(){SettingsRepository.Snapshot s=settings(SearchEngines.Provider.BING);NewTabView.Model m=NewTabView.Model.fromNative(s,null,2);assertFalse(m.sameSettings(s.withSearch(SearchEngines.Provider.GOOGLE)));assertTrue(m.sameSettings(new SettingsRepository.Snapshot(5,s.searchProvider(),true,true)));assertFalse(m.sameSettings(new SettingsRepository.Snapshot(4,s.searchProvider(),false,false,SettingsRepository.NewTabBackground.WHITE,true)));assertFalse(m.sameSettings(new SettingsRepository.Snapshot(4,s.searchProvider(),false,false,s.newTabBackground(),false)));assertFalse(m.sameSettings(null));}
    @Test public void packagedActualBrandResourcesMatchPhotoAndWhiteModes(){for(SearchEngines.Provider p:SearchEngines.Provider.values()){SettingsRepository.Snapshot s=settings(p);NewTabView.Model photo=NewTabView.Model.fromNative(s,null,2),white=NewTabView.Model.fromNative(s.withNewTab(SettingsRepository.NewTabBackground.WHITE,true),null,2);assertTrue(photo.logoResource()!=0);assertEquals(photo.iconResource(),white.iconResource());assertFalse(white.photo());if(p==SearchEngines.Provider.BAIDU)assertEquals(photo.logoResource(),white.logoResource());else assertNotEquals(photo.logoResource(),white.logoResource());}assertEquals(R.drawable.rb_brand_google_logo_light_photo,NewTabView.Model.fromNative(settings(SearchEngines.Provider.GOOGLE),null,0).logoResource());}
    @Test public void commonOmniboxResolverRecognizesUrlsAndUsesActualEngineForKeywords(){String raw=NewTabView.Query.require("example.test/path");assertEquals(SearchEngines.Kind.WEB,SearchEngines.resolveInput(raw,SearchEngines.Provider.BAIDU).kind());assertEquals("https://example.test/path",SearchEngines.resolveInput(raw,SearchEngines.Provider.BAIDU).url());assertTrue(SearchEngines.resolveInput(NewTabView.Query.require("普通 搜索"),SearchEngines.Provider.DUCKDUCKGO).url().startsWith("https://duckduckgo.com/"));assertEquals(SearchEngines.Kind.NEW_TAB,SearchEngines.resolveInput(NewTabView.Query.require("about:blank"),SearchEngines.Provider.GOOGLE).kind());assertThrows(IllegalArgumentException.class,()->SearchEngines.resolveInput(NewTabView.Query.require("javascript:alert(1)"),SearchEngines.Provider.GOOGLE));}
    @Test public void imeAndButtonShareOnePreparationGuard(){NewTabView.Submission s=new NewTabView.Submission();assertTrue(s.begin());assertFalse(s.begin());s.spendBeforeHandoff();assertTrue(s.handedOff());assertFalse(s.begin());assertThrows(IllegalStateException.class,s::preparationFailed);assertThrows(IllegalStateException.class,s::spendBeforeHandoff);}
    @Test public void failedPreparationCanBeExplicitlyRetriedButNotUnknownHandoff(){NewTabView.Submission s=new NewTabView.Submission();assertThrows(IllegalStateException.class,s::spendBeforeHandoff);assertTrue(s.begin());s.preparationFailed();assertFalse(s.handedOff());assertTrue(s.begin());s.spendBeforeHandoff();assertFalse(s.begin());}
}
